  "knowledge": "Visitor Capacity Safety Factor (VCSF)",
  "description": "Determines the safe visitor capacity for exhibition halls containing sensitive artifacts.",
  "definition": "Calculated as: 'Visitor Impact Risk (VIR)' / ('Artifact Vulnerability Score (AVS)' * 0.1). Lower values indicate safer visitor capacities."
}

{
  "id": 19,
  "knowledge": "Visitor Crowd Risk",
  "description": "Identifies exhibition halls where high visitor numbers pose risks to artifact safety.",
  "definition": "Occurs when the 'Visitor Impact Risk (VIR)' score is greater than 5 AND any artifact in the hall has the lowest security level rating."
}

{
  "id": 10,
  "knowledge": "Visitor Impact Risk (VIR)",
  "description": "Assesses the risk posed by visitor traffic to artifacts in exhibition halls.",
  "definition": "Calculated as: (Daily Visitor Count * Visitor Flow Rate * Average Dwell Time in Minutes) / 1000. The visitor flow rate is numerically mapped: Low=1, Medium=3, High=5."
}

